package com.greenocean.backend;
import com.greenocean.backend.community.service.GroupMemberships;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import java.util.*;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
class PhaseM2ConcurrencyTest extends PhaseLFixtures {
 @Autowired GroupMemberships memberships;UUID owner,target,group;List<UUID> users;
 @BeforeEach void isolated(){users=new ArrayList<>();for(int i=0;i<2;i++){UUID id=UUID.randomUUID();users.add(id);db.update("INSERT INTO users(id,email,password_hash,status,email_verified) VALUES(?,?,'synthetic-only','ACTIVE',TRUE)",id,"m2-race-"+id+"@example.test");}owner=users.get(0);target=users.get(1);group=UUID.randomUUID();db.update("INSERT INTO communities(id,name,slug,privacy_type,created_by) VALUES(?,?,?,'HIDDEN',?)",group,"Synthetic race "+group,"g-"+group,owner);db.update("INSERT INTO community_members(community_id,user_id,role,rules_version_ack) VALUES(?,?,'OWNER',1)",group,owner);}
 @AfterEach void cleanup(){db.update("DELETE FROM notifications WHERE user_id IN(?,?)",owner,target);db.update("DELETE FROM audit_logs WHERE actor_user_id IN(?,?)",owner,target);db.update("DELETE FROM communities WHERE id=?",group);db.update("DELETE FROM users WHERE id IN(?,?)",owner,target);}
 List<String> race(Callable<String> first,Callable<String> second)throws Exception{var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=pool.submit(()->{start.await();return first.call();});var b=pool.submit(()->{start.await();return second.call();});start.countDown();return List.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS));}finally{pool.shutdownNow();pool.awaitTermination(10,TimeUnit.SECONDS);}}
 @Test void concurrentInviteAcceptanceCreatesOneMembership()throws Exception{UUID id=(UUID)memberships.invite(group,owner,target,UUID.randomUUID()).get("id");Callable<String> accept=()->{memberships.invitation(id,target,"ACCEPT",1);return "ACCEPTED";};assertThat(race(accept,accept)).containsOnly("ACCEPTED");assertThat(db.queryForObject("SELECT count(*) FROM community_members WHERE community_id=? AND user_id=?",Integer.class,group,target)).isEqualTo(1);}
 @Test void revocationAndAcceptanceHaveAConsistentCommittedWinner()throws Exception{UUID id=(UUID)memberships.invite(group,owner,target,UUID.randomUUID()).get("id");race(()->{try{memberships.invitation(id,target,"ACCEPT",1);return "ACCEPTED";}catch(com.greenocean.backend.common.exception.NotFoundException expected){return "REVOKED";}},()->{try{memberships.invitation(id,owner,"REVOKE",0);return "REVOKED";}catch(com.greenocean.backend.common.exception.ConflictException expected){return "ACCEPTED";}});String status=db.queryForObject("SELECT status FROM community_invitations WHERE id=?",String.class,id);assertThat(db.queryForObject("SELECT active_group_member(?,?)",Boolean.class,group,target)).isEqualTo(status.equals("ACCEPTED"));}
 @Test void cancellationAndPrivateApprovalCannotReplayEachOther()throws Exception{
  // Insert a PRIVATE fixture rather than changing any activated group's privacy.
  db.update("DELETE FROM communities WHERE id=?",group);db.update("INSERT INTO communities(id,name,slug,privacy_type,created_by) VALUES(?,?,?,'PRIVATE',?)",group,"Synthetic race "+group,"g-"+group,owner);db.update("INSERT INTO community_members(community_id,user_id,role,rules_version_ack) VALUES(?,?,'OWNER',1)",group,owner);memberships.join(group,target,1);
  race(()->{try{memberships.cancel(group,target,1);return "CANCELLED";}catch(com.greenocean.backend.common.exception.ConflictException expected){return "APPROVED";}},()->{try{memberships.resolve(group,target,owner,1,true);return "APPROVED";}catch(com.greenocean.backend.common.exception.ConflictException expected){return "CANCELLED";}});String status=db.queryForObject("SELECT status FROM community_join_requests WHERE community_id=? AND requester_id=?",String.class,group,target);assertThat(db.queryForObject("SELECT active_group_member(?,?)",Boolean.class,group,target)).isEqualTo(status.equals("APPROVED"));
 }
}
